using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;

namespace AlgoDemos.String
{
    public class JumpGame7
    {



        string _s = "";
        int _minJump = -1;
        int _maxJump = -1;
        int _n = -1;
        HashSet<int> _visited = new HashSet<int>();
        public bool CanReachDFS(int parent)
        {
            if(_visited.Contains(parent))
            {
                return false;
            }
            
            if (parent == _n - 1)
            {
                return true;
            }

            int start = parent + _minJump;
            int end = parent + _maxJump;
            if (start >= _n)
            {
                return false;
            }

            for (int j = Math.Min(_n - 1, end); j >= start; j--)
            {
                try
                {
                    if (_visited.Contains(j))
                    {
                        continue;
                    }

                    if (_s[j] == '0')
                    {
                        if (!_visited.Contains(j))
                        {
                            if (CanReachDFS(j))
                            {
                                return true;
                            }
                            else
                            {
                                _visited.Add(j);
                            }
                        }
                    }
                    else
                    {
                        _visited.Add(j);
                    }
                }
                catch(Exception ex)
                {
                    int ii = 38;
                }
            }

            _visited.Add(parent);
            return false;

        }


        private bool MaxRangeNumbersAreAllOnes()
        {
            int counter = 0;
            for (int y = 0; y < _n - 1; y++)
            {
                if (_s[y] == '0')
                {
                    counter = 0;
                }
                else
                {
                    counter++;
                    if (counter == _maxJump)
                    {
                        return true;
                    }
                }
            }
            return false;
        }

        /// <summary>
        /// passes leetcode. 13 ms beats 16%. 60 MB memory beats 5.11%
        /// </summary>
        /// <param name="s"></param>
        /// <param name="minJump"></param>
        /// <param name="maxJump"></param>
        /// <returns></returns>
        public bool CanReach(string s, int minJump, int maxJump)
        {
            _s = s;
            
            _n = s.Length;
            _visited.Clear();
            _minJump = minJump;
            _maxJump = maxJump;

            if (_n == 0 || s[_n - 1] == '1' || MaxRangeNumbersAreAllOnes())
            {
                return false;
            }

            return CanReachDFS(0);
        }


        public static void Demo()
        {
            var j = new JumpGame7();
            string s = "";
            bool solutn = false;

            s = "011010";
            solutn = j.CanReach(
                "0000000000",
                2, 3);
            Console.WriteLine($"solution={solutn} should be True");
            
            solutn = j.CanReach(
                "0111111111111111111111111111111111011111111111111111111111111111111110",
                19, 38);
            Console.WriteLine($"solution={solutn} should be True");

            
            solutn = false;
            solutn = j.CanReach(
                "0000000000",
                1, 1);
            Console.WriteLine($"solution={solutn} should be True");

            
            solutn = false;
            solutn = j.CanReach(
                "000100100010",
                1, 2);
            Console.WriteLine($"solution={solutn} should be True");

            
            s = "";
            solutn = false;
            solutn = j.CanReach(
                s,
                1, 99999);
            Console.WriteLine($"solution={solutn} should be False");

            
            s = "011001110001000";
            solutn = false;
            solutn = j.CanReach(
                s,
                3, 5);
            Console.WriteLine($"solution={solutn} should be True");

            
            s = "01101110";
            solutn = false;
            solutn = j.CanReach(
                s,
                2, 3);
            Console.WriteLine($"solution={solutn} should be False");

            
            s = "00111010";
            solutn = false;
            solutn = j.CanReach(
                s,
                3, 5);
            Console.WriteLine($"solution={solutn} should be False");

            
            s = "0000000000";
            solutn = false;
            solutn = j.CanReach(
                s,
                2, 5);
            Console.WriteLine($"solution={solutn} should be True");
            
            
            s = "";
            
            solutn = false;
            solutn = j.CanReach(
                s,
                1, 49999);
            Console.WriteLine($"solution={solutn} should be False");
            
            
            
        }
    }
}
